21	// DEVDESK-579 (NX-12), step 6, decision Q3 = 3-A: a Nexus group on a connector of
22	// its own (a dedicated HTTP port) answers /v2/_catalog with the UNION of its
23	// members' names and no attribution (measured, Nexus 3.98.1-01, fixtures
24	// catalog-group-connector-30482--*). Its discovered members have no address of
25	// their own (the group's URL, no prefix), so the search treats them as ONE unit:
26	// the group. One walk, rows under the group's label, no duplicate, no name
27	// attributed to a member.
28	//
29	// The label of that unit is groupUnitSuffix appended to the group's label
30	// ("nx (group)"). It is one constant of the production code, and every assertion
31	// below reads it from there, so the label the UX settles on changes in one place.
32	// It shows in: the Registry column of the level 1 rows, the header lines that
33	// name a registry (Cached only, Failed, Refused, No result), the `r` filter
34	// token, the Registry column of the tag table a row opens, and the journal.
35	// An undiscovered group is the group itself, offered under its own plain label.
36	
37	// benchConnectorPort is the recorded Host of the group's Docker connector.
38	const benchConnectorPort = "127.0.0.1:30482"
39	
40	// groupUnitLabel is what the unit of group slug is labelled with.
41	func groupUnitLabel(alias string) string { return alias + groupUnitSuffix }
42	
43	// benchGroupAs is the Nexus group "nx" at base, read as id: anonymous sends
44	// nothing, any other identity is the bench account stored for base's host in the
45	// docker config, the way the browser finds a login.
46	func benchGroupAs(t *testing.T, id nexusfixture.Identity, base string) config.RegistryItem {
47		t.Helper()
48		g := nexusGroup()
49		g.URL = base
50		if id == nexusfixture.Anonymous {
51			g.AuthMode = config.AuthAnonymous
52			return g
53		}
54		u, err := url.Parse(base)
55		if err != nil {
56			t.Fatal(err)
57		}
58		writeDockerConfig(t, map[string]any{
59			"auths": map[string]any{u.Host: map[string]string{"auth": encodeAuth(fakenexus.User(id), fakenexus.Password)}},
60		})
61		g.AuthMode = config.AuthCredentials
62		return g
63	}
