65	// connectorMembers are members of "nx" the way discovery stores them for a group
66	// on a connector of its own: the group's URL and no prefix, whatever the member.
67	func connectorMembers(base string, aliases ...string) map[string]cache.RegistryGroupEntry {
68		var members []cache.RegistryGroupMember
69		for _, a := range aliases {
70			members = append(members, cache.RegistryGroupMember{Alias: a, URL: base})
71		}
72		return map[string]cache.RegistryGroupEntry{"nx": {Members: members}}
73	}
