75	// discoveredGroupModel opens the browser on the group "nx" read as id, on the
76	// recorded connector, with two discovered members that have no address of their own.
77	func discoveredGroupModel(t *testing.T, id nexusfixture.Identity) (Model, *fakenexus.Server, []nexusfixture.Fixture, string) {
78		t.Helper()
79		s, fixtures := nexusFake(t)
80		base := s.URL(benchConnectorPort)
81		withImageSearcher(t, nexusOnlySearcher(t))
82		m := modelWithGroups(t, []config.RegistryItem{benchGroupAs(t, id, base)}, connectorMembers(base, "docker-hosted", "docker-proxy"))
83		return m, s, fixtures, base
84	}
