86	// runLotAll submits text, runs every search of the lot and feeds the answers back.
87	// It returns the answers, so a test counts the walks the lot really made (a lot of
88	// one search is not a batch, which runLot cannot tell).
89	func runLotAll(t *testing.T, m Model, text string) (Model, []ImageSearchResultMsg) {
90		t.Helper()
91		m, cmd := submitRaw(t, m, text)
92		if cmd == nil || m.registryBrowser.state != browserStateImages {
93			t.Fatalf("the search did not start (state %d)", m.registryBrowser.state)
94		}
95		var results []ImageSearchResultMsg
96		for _, msg := range testutil.Msgs(cmd) {
97			if r, ok := msg.(ImageSearchResultMsg); ok {
98				results = append(results, r)
99			}
100		}
101		for _, r := range results {
102			m = feed(t, m, r)
103		}
104		return m, results
105	}
