107	// wantExactHits checks the requests the fake answered, fixture by fixture: each
108	// named fixture the given number of times, every other one never.
109	func wantExactHits(t *testing.T, s *fakenexus.Server, fixtures []nexusfixture.Fixture, want map[string]int) {
110		t.Helper()
111		known := map[string]bool{}
112		for _, f := range fixtures {
113			known[f.Name] = true
114			if got := s.Hits(f.Name); got != want[f.Name] {
115				t.Errorf("Hits(%s) = %d, want %d", f.Name, got, want[f.Name])
116			}
117		}
118		for name := range want {
119			if !known[name] {
120				t.Fatalf("the test names an unknown fixture %q", name)
121			}
122		}
123	}
