128	// answerKeys are the entry keys the answers of a lot came for.
129	func answerKeys(results []ImageSearchResultMsg) []string {
130		var keys []string
131		for _, r := range results {
132			keys = append(keys, r.EntryKey)
133		}
134		return keys
135	}
