141	// connectorTestGroup is a group of the given provider at url, with a prefix of
142	// its own when prefix is not empty.
143	func connectorTestGroup(slug, url, prefix, provider string) config.RegistryItem {
144		return config.RegistryItem{
145			Slug: slug, Alias: slug, Kind: config.KindGroup, Provider: provider,
146			URL: url, RepoPrefix: prefix, AuthMode: config.AuthAnonymous,
147		}
148	}
