150	// groupMemberEntry is the picker entry buildEntries makes for a discovered member.
151	func groupMemberEntry(g config.RegistryItem, alias, url, prefix string) browserRegistryEntry {
152		return browserRegistryEntry{
153			URL: url, Alias: alias, repoPrefix: prefix, Slug: g.Slug,
154			ParentAlias: browserAlias(g), ParentSlug: g.Slug, parentURL: g.URL,
155			authMode: g.AuthMode, cachedOnly: config.IsNexusGroup(g),
156			catalogUnderPrefix: config.IsNexusGroup(g) && prefix != "",
157			key:                memberKey(g.Slug, url, prefix),
158		}
159	}
