161	// TestSearchUnits pins searchUnits: it turns the entries a search is asked on into what it walks: the
162	// members of a group that share the group's address (its URL and its prefix, so
163	// the same catalog under the same identity) are replaced by ONE entry, the group,
164	// standing where the first of them stood. Everything else is kept as it is, in
165	// order. It is pure: same input, same output, the input untouched.
166	func TestSearchUnits(t *testing.T) {
167		const gURL = "nexus.example.com:5001"
168		nx := connectorTestGroup("nx", gURL, "", config.ProviderNexus)
169		ob := connectorTestGroup("ob", "other.example.com:5002", "", config.ProviderNexus)
170		gn := connectorTestGroup("gn", "reg.example.com", "", config.ProviderGeneric)
171		pg := connectorTestGroup("pg", "p.example.com:5003", "p", config.ProviderNexus)
172		groups := map[string]config.RegistryItem{"nx": nx, "ob": ob, "gn": gn, "pg": pg}
173	
174		a := groupMemberEntry(nx, "docker-hosted", gURL, "")
175		b := groupMemberEntry(nx, "docker-proxy", gURL, "")
176		p1 := groupMemberEntry(nx, "docker-hosted", gURL, "docker-hosted")
177		p2 := groupMemberEntry(nx, "docker-proxy", gURL, "docker-proxy")
178		elsewhere := groupMemberEntry(nx, "docker-other", "elsewhere.example.com", "")
179		orphan := groupMemberEntry(config.RegistryItem{Slug: "zz", Alias: "zz"}, "docker-hosted", gURL, "")
180		obA := groupMemberEntry(ob, "docker-hosted", ob.URL, "")
181		obB := groupMemberEntry(ob, "docker-proxy", ob.URL, "")
182		gnA := groupMemberEntry(gn, "team-a", gn.URL, "")
183		gnB := groupMemberEntry(gn, "team-b", gn.URL, "")
184		pgOwn := groupMemberEntry(pg, "own", pg.URL, "p")
185		pgBare := groupMemberEntry(pg, "bare", pg.URL, "")
186		// What buildEntries makes of a group nobody discovered (the group itself) and
187		// of standalone registries: none of them is a member.
188		groupAlone := browserRegistryEntry{URL: gURL, Alias: "nx", Slug: "nx", key: "nx", cachedOnly: true, authMode: config.AuthAnonymous}
189		soloSameHost := browserRegistryEntry{URL: gURL, Alias: "solo", Slug: "solo", key: "solo", authMode: config.AuthAnonymous}
190		soloPrefixed := browserRegistryEntry{URL: gURL, Alias: "other", Slug: "other", key: "other", repoPrefix: "p", authMode: config.AuthAnonymous}
191		hub := browserRegistryEntry{URL: "docker.io", Alias: "hub", Slug: "hub", key: "hub", authMode: config.AuthAnonymous}
192	
193		tests := []struct {
194			name    string
195			entries []browserRegistryEntry
196			// wantKeys is the keys of the result, in order; wantUnits the ones among
197			// them that are a group unit (not an entry of the input).
198			wantKeys  []string
199			wantUnits []string
200		}{
201			{name: "two members with no address of their own are one unit", entries: []browserRegistryEntry{a, b}, wantKeys: []string{"nx"}, wantUnits: []string{"nx"}},
202			{name: "one member with no address of its own is still the group", entries: []browserRegistryEntry{a}, wantKeys: []string{"nx"}, wantUnits: []string{"nx"}},
203			{name: "members that each have a path stay as they are", entries: []browserRegistryEntry{p1, p2}, wantKeys: []string{p1.key, p2.key}},
204			{name: "a mix: the unit stands where the first bare member stood", entries: []browserRegistryEntry{a, p1, b}, wantKeys: []string{"nx", p1.key}, wantUnits: []string{"nx"}},
205			{name: "a mix with path members on both sides", entries: []browserRegistryEntry{p1, a, p2, b}, wantKeys: []string{p1.key, "nx", p2.key}, wantUnits: []string{"nx"}},
206			{name: "a group nobody discovered is not a member", entries: []browserRegistryEntry{groupAlone}, wantKeys: []string{"nx"}},
207			{name: "generic entries are untouched, even on the group's address", entries: []browserRegistryEntry{hub, soloSameHost, soloPrefixed}, wantKeys: []string{"hub", "solo", "other"}},
208			{name: "an undiscovered group and a standalone entry beside a discovered one", entries: []browserRegistryEntry{hub, a, b, soloSameHost}, wantKeys: []string{"hub", "nx", "solo"}, wantUnits: []string{"nx"}},
209			{name: "members of two groups are two units, by first appearance", entries: []browserRegistryEntry{a, obA, b, obB}, wantKeys: []string{"nx", "ob"}, wantUnits: []string{"nx", "ob"}},
210			{name: "a member whose group is unknown is untouched", entries: []browserRegistryEntry{orphan}, wantKeys: []string{orphan.key}},
211			{name: "a member on another host than its group has an address of its own", entries: []browserRegistryEntry{elsewhere, a}, wantKeys: []string{elsewhere.key, "nx"}, wantUnits: []string{"nx"}},
212			{name: "the group's prefix is part of its address", entries: []browserRegistryEntry{pgOwn, pgBare}, wantKeys: []string{"pg", pgBare.key}, wantUnits: []string{"pg"}},
213			{name: "rule is the same address, not Nexus", entries: []browserRegistryEntry{gnA, gnB}, wantKeys: []string{"gn"}, wantUnits: []string{"gn"}},
214			{name: "no entry", entries: nil, wantKeys: nil},
215		}
216		for _, tt := range tests {
217			t.Run(tt.name, func(t *testing.T) {
218				in := slices.Clone(tt.entries)
219				got := searchUnits(tt.entries, groups)
220	
221				var keys []string
222				for _, e := range got {
223					keys = append(keys, e.key)
224				}
225				if !slices.Equal(keys, tt.wantKeys) {
226					t.Fatalf("keys = %v, want %v", keys, tt.wantKeys)
227				}
228				if !slices.Equal(tt.entries, in) {
229					t.Errorf("the input was modified: %v, was %v", tt.entries, in)
230				}
231				if again := searchUnits(tt.entries, groups); !slices.Equal(again, got) {
232					t.Errorf("a second call differs: %v, then %v", again, got)
233				}
234	
235				var units []string
236				for _, e := range got {
237					if !slices.Contains(tt.entries, e) {
238						units = append(units, e.key)
239						checkGroupUnit(t, e, groups[e.key], tt.entries)
240					}
241				}
242				if !slices.Equal(units, tt.wantUnits) {
243					t.Errorf("group units = %v, want %v", units, tt.wantUnits)
244				}
245			})
246		}
247	}
