281	// ---- the group's connector, discovered ------------------------------------
282	
283	// The core of 3-A, on the measured answer of the connector: two discovered
284	// members with no address of their own are searched as ONE unit. One walk (one
285	// recorded request), one verdict under the group's key, rows under the group's
286	// label, no duplicate, and no name attributed to a member.
287	func TestDiscoveredGroupMembersOnTheConnectorAreSearchedAsTheGroup(t *testing.T) {
288		tests := []struct {
289			name  string
290			query string
291			repos []string // the union, as the connector gave it
292		}{
293			{"a name only the hosted repository holds", "api", []string{"api", "team/api"}},
294			{"a name both repositories hold is listed once", "base", []string{"shared/base"}},
295			{"a name only the proxy repository holds", "mirror", []string{"mirror/cached", "mirror/uncached"}},
296		}
297		for _, tt := range tests {
298			t.Run(tt.name, func(t *testing.T) {
299				m, s, fixtures, base := discoveredGroupModel(t, nexusfixture.Admin)
300				label := groupUnitLabel("nx")
301	
302				m, results := runLotAll(t, m, tt.query)
303	
304				// One walk: one answer, one request, on the connector's root catalog.
305				if len(results) != 1 || results[0].EntryKey != "nx" {
306					t.Fatalf("%d answers, for %v; want exactly one, for the group's key \"nx\"", len(results), answerKeys(results))
307				}
308				wantExactHits(t, s, fixtures, map[string]int{"page-group-n1000--admin": 1})
309	
310				var want []string
311				for _, r := range tt.repos {
312					want = append(want, "nx:"+r)
313				}
314				if got := repoKeys(m); !slices.Equal(got, sorted(want)) {
315					t.Errorf("rows = %v, want %v (under the group, no member)", got, sorted(want))
316				}
317				u, _ := url.Parse(base)
318				for _, r := range searchRows(m) {
319					if r.label != label {
320						t.Errorf("row %s: label = %q, want the group's %q", r.img.Repo, r.label, label)
321					}
322					if want := u.Host + "/" + r.img.Repo; r.ref != want {
323						t.Errorf("row %s: reference = %q, want %q (the group's address, pullable)", r.img.Repo, r.ref, want)
324					}
325				}
326	
327				// One verdict, under the group's key; the members have none.
328				outcomes := m.RegistryBrowserOutcomes()
329				if len(outcomes) != 1 {
330					t.Errorf("outcomes = %v, want only the group's", outcomes)
331				}
332				wantVerdict(t, m, "nx", imagesearch.VerdictOK)
333	
334				// Header: the count of the rows, and the unit named once as cached only.
335				keys, vals := headerLines(m)
336				if want := []string{"Images", "Cached only"}; !slices.Equal(keys, want) {
337					t.Errorf("header keys = %v, want %v", keys, want)
338				}
339				if vals["Images"] != strconv.Itoa(len(tt.repos)) {
340					t.Errorf("Images = %q, want %d", vals["Images"], len(tt.repos))
341				}
342				if vals["Cached only"] != label {
343					t.Errorf("Cached only = %q, want %q once, not once per member", vals["Cached only"], label)
344				}
345	
346				// The picker is not the search: it still shows the group and its two members.
347				if n := len(m.registryBrowser.entries); n != 2 {
348					t.Errorf("the picker holds %d entries, want its 2 members", n)
349				}
350			})
351		}
352	}
