354	// The label of the unit is on the screen, in the Registry column, and a member's
355	// label (nx/docker-hosted) is nowhere: the lines are not attributed to a member.
356	func TestTheGroupUnitLabelIsOnTheScreen(t *testing.T) {
357		m, _, _, _ := discoveredGroupModel(t, nexusfixture.Admin)
358		m, _ = runLotAll(t, m, "api")
359	
360		screen := ansi.Strip(m.Render())
361		label := groupUnitLabel("nx")
362		if n := strings.Count(screen, label); n != 2 {
363			t.Errorf("the screen shows %q %d times, want once per row (2):\n%s", label, n, screen)
364		}
365		for _, member := range []string{"nx/docker-hosted", "nx/docker-proxy"} {
366			if strings.Contains(screen, member) {
367				t.Errorf("the screen names the member %q, which the answer does not attribute anything to:\n%s", member, screen)
368			}
369		}
370	}
