372	// A refusal or a failure of the connector is one verdict, under the group's label,
373	// from one request: not one per member, not twice in the header.
374	func TestAFailingGroupConnectorIsOneVerdictUnderTheGroupLabel(t *testing.T) {
375		tests := []struct {
376			status  int
377			verdict imagesearch.Verdict
378			header  string
379		}{
380			{http.StatusNotFound, imagesearch.VerdictRefused, "Refused"},
381			{http.StatusServiceUnavailable, imagesearch.VerdictFailed, "Failed"},
382		}
383		for _, tt := range tests {
384			t.Run(strconv.Itoa(tt.status), func(t *testing.T) {
385				srv := newPathServer(t, map[string]int{"/v2/_catalog": tt.status})
386				withImageSearcher(t, wiredLikeProduction(srv.Server))
387	
388				m := modelWithGroups(t, []config.RegistryItem{anonymousNexusGroup(srv.URL)}, connectorMembers(srv.URL, "docker-hosted", "docker-proxy"))
389				m, results := runLotAll(t, m, "nginx")
390	
391				if len(results) != 1 {
392					t.Fatalf("answers = %d, want 1 (one unit)", len(results))
393				}
394				if n := srv.requests("/v2/_catalog"); n != 1 || srv.total() != 1 {
395					t.Errorf("the connector got %d requests on the root, %d in all, want 1", n, srv.total())
396				}
397				wantVerdict(t, m, "nx", tt.verdict)
398				if got := m.RegistryBrowserOutcomes(); len(got) != 1 {
399					t.Errorf("outcomes = %v, want only the group's", got)
400				}
401				_, vals := headerLines(m)
402				if want := groupUnitLabel("nx"); vals[tt.header] != want {
403					t.Errorf("%s = %q, want %q", tt.header, vals[tt.header], want)
404				}
405				if rows := rowsOf(m); len(rows) != 0 {
406					t.Errorf("rows = %v, want none", rows)
407				}
408			})
409		}
410	}
