412	// → on a row of the unit lists the tags of the group itself: the connector, the
413	// row's repository as is, the group's credentials, and the tag table carries the
414	// unit's label (the unit is gone from the picker, so the lot must still resolve it).
415	func TestArrowOnAGroupUnitRowListsTheGroupsTags(t *testing.T) {
416		m, _, _, base := discoveredGroupModel(t, nexusfixture.Admin)
417		rec := withFullTagRecorder(t)
418		m, _ = runLotAll(t, m, "api")
419	
420		if r, ok := m.registryBrowser.searchTable.Selected(); ok && r.img.Repo != "api" {
421			m = feed(t, m, testutil.Key("down"))
422		}
423		row, ok := m.registryBrowser.searchTable.Selected()
424		if !ok || row.img.Repo != "api" {
425			t.Fatalf("selected row = %+v (%v), want the api row", row.img, ok)
426		}
427		m, cmd := step(t, m, testutil.Key("right"))
428		m = feed(t, m, testutil.Msgs(cmd)...)
429	
430		if m.registryBrowser.state != browserStateTags {
431			t.Fatalf("state = %d, want the tag table (%d)", m.registryBrowser.state, browserStateTags)
432		}
433		rec.mu.Lock()
434		calls := slices.Clone(rec.calls)
435		rec.mu.Unlock()
436		want := fullTagCall{apiURL: base, repo: "api", user: fakenexus.User(nexusfixture.Admin), pass: fakenexus.Password}
437		if len(calls) != 1 || calls[0] != want {
438			t.Errorf("tag requests = %+v, want exactly %+v", calls, want)
439		}
440		tags := m.registryBrowser.tagTable.Visible()
441		if len(tags) == 0 {
442			t.Fatal("the tag table is empty")
443		}
444		for _, r := range tags {
445			if r.label != groupUnitLabel("nx") || r.tag.EntryKey != "nx" {
446				t.Errorf("tag row = label %q, key %q, want %q and \"nx\"", r.label, r.tag.EntryKey, groupUnitLabel("nx"))
447			}
448		}
449	}
