451	// A unit lives as long as its lot. A new search that has no unit leaves none behind
452	// in entryFor (which every label, `r` stop and → resolves through), a new search
453	// that has one makes it again, and the picker never held it.
454	func TestAGroupUnitBelongsToItsLotOnly(t *testing.T) {
