func (b *RegistryBrowser) submit(action formAction) (*RegistryBrowser, tea.Cmd) {
	repo := strings.TrimSpace(b.repoInput.Value())
	if repo == "" {
		return b, nil
	}
	var entries []browserRegistryEntry
	for _, entry := range b.entries {
		if b.selected(entry) {
